insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_GTE_16","title":"¿Habrá 16 o más carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_gte","n":16},"priority":0,"cooldown":2,"tags":["total"]},{"code":"BOTH_GTE_6","title":"¿Ambos equipos anotarán 6 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_gte","n":6},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"LOSER_GTE_6","title":"¿Hasta el perdedor anota 6 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_gte","n":6},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"HOME_GTE_8","title":"¿El local llega a 8 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_gte","n":8},"priority":0,"cooldown":2,"tags":["resultado"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;